Here's how to count items in a list:

```python
# Method 1: Using len()
def count_items_v1(lst):
    return len(lst)

# Method 2: Count specific item
def count_specific(lst, item):
    return lst.count(item)

# Method 3: Manual counting
def count_items_v2(lst):
    count = 0
    for item in lst:
        count += 1
    return count

# Examples
fruits = ['apple', 'banana', 'apple', 'orange']
print(count_items_v1(fruits))        # 4
print(count_specific(fruits, 'apple'))  # 2
```

Here's how to convert strings to uppercase:

```python
# Method 1: Using upper() method
def to_uppercase_v1(text):
    return text.upper()

