Here's a function to find the minimum of two numbers:

```python
# Method 1: Using if-else
def find_min(a, b):
    if a < b:
        return a
    else:
        return b

# Method 2: Using built-in min()
def find_min_v2(a, b):
    return min(a, b)

# Method 3: Using ternary operator
def find_min_v3(a, b):
    return a if a < b else b

# Examples
print(find_min(10, 5))   # 5
print(find_min(3, 8))    # 3
```
